{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-04",
  "sketch": {
    "components": ["Image resize service", "URL fetcher", "Resize engine"],
    "dataStores": ["Internal databases"],
    "externalServices": ["Arbitrary attacker-supplied URLs", "Internal metadata service"],
    "trustBoundaries": ["VPC boundary", "Service-to-internal-metadata boundary"],
    "dataClasses": [],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "Tampering",
      "title": "SSRF via URL fetch reaches internal metadata service",
      "scenario": "An attacker supplies a URL parameter pointing at the internal metadata endpoint or other internal-only hosts. The service runs inside the VPC next to the metadata service and databases, downloads whatever URL it's given, and returns the result, letting the attacker read internal metadata, credentials, or hit internal-only APIs that should never be reachable from outside.",
      "component": "Image resize service - URL fetcher",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {"quote": "The image service accepts a URL parameter, downloads the image from that URL, resizes it and returns it. It runs inside our VPC next to the internal metadata service and databases."}
      ],
      "asvs": ["V12.6.1", "V5.1.4"],
      "cwe": ["CWE-918"],
      "plainLanguage": "Someone could trick the resizer into fetching internal secrets instead of a picture.",
      "requirement": {
        "title": "Block SSRF to internal/metadata hosts",
        "given": "A user-supplied URL is passed to the fetcher",
        "when": "The URL resolves to a private IP range, the metadata service, or localhost",
        "then": "The request is rejected before any network call is made, using an allowlist of permitted external hosts/schemes"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Response reflects fetched content, enabling data exfiltration via resize results",
      "scenario": "Because the service downloads from any URL and returns the processed result, an attacker can point it at internal services (e.g. metadata or databases reachable via HTTP) and read back sensitive data disguised as an 'image' response, bypassing the VPC network boundary that was meant to keep those services internal-only.",
      "component": "Image resize service",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {"quote": "It runs inside our VPC next to the internal metadata service and databases."}
      ],
      "asvs": ["V12.6.1"],
      "cwe": ["CWE-200"],
      "plainLanguage": "The service could be used as a proxy to leak internal data it shouldn't be able to reach.",
      "requirement": {
        "title": "Restrict and validate fetch destinations",
        "given": "The service is about to fetch a URL",
        "when": "It resolves the hostname",
        "then": "Only approved external hosts are allowed; internal IP ranges and the metadata service are explicitly denied, including via DNS rebinding and redirects"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Unbounded/huge file fetch and decompression bomb via arbitrary URL",
      "scenario": "An attacker provides a URL to an extremely large file or a crafted 'image' (e.g. a decompression bomb), causing the service to download and process huge amounts of data, exhausting memory/CPU/disk and degrading or crashing the service for other users.",
      "component": "Image resize service - Resize engine",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {"quote": "downloads the image from that URL, resizes it and returns it"}
      ],
      "asvs": ["V12.1.1"],
      "cwe": ["CWE-400"],
      "plainLanguage": "A booby-trapped 'image' could overload the service and take it down for everyone.",
      "requirement": {
        "title": "Limit fetch and processing size",
        "given": "A URL is being fetched for resizing",
        "when": "The response exceeds a configured size/time limit or decoded pixel dimensions exceed a safe maximum",
        "then": "The fetch/processing is aborted and the request is rejected"
      }
    },
    {
      "stride": "Tampering",
      "title": "Protocol/scheme abuse via non-HTTP URL schemes",
      "scenario": "If the URL parameter isn't restricted to http/https, an attacker could supply file://, gopher://, dict:// or similar schemes to read local files or interact with internal services in unexpected ways, since the service 'accepts a URL parameter' with no stated validation.",
      "component": "Image resize service - URL fetcher",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {"quote": "The image service accepts a URL parameter, downloads the image from that URL"}
      ],
      "asvs": ["V12.6.1"],
      "cwe": ["CWE-918"],
      "plainLanguage": "If the link format isn't checked, attackers might use tricks like 'file://' to read local files instead of fetching a web image.",
      "requirement": {
        "title": "Enforce URL scheme allowlist",
        "given": "A URL parameter is submitted",
        "when": "The scheme is anything other than https (or an explicitly approved list)",
        "then": "The request is rejected"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "No stated authentication/authorization lets any internal caller abuse the fetch-and-resize capability as an SSRF pivot",
      "scenario": "The design states no auth signal and the service sits next to sensitive internal systems; any party able to reach this internal API could use it to probe or pivot into the metadata service and databases without needing separate credentials for those internal targets.",
      "component": "Image resize service",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {"quote": "It runs inside our VPC next to the internal metadata service and databases."}
      ],
      "asvs": ["V4.1.1"],
      "cwe": ["CWE-862"],
      "plainLanguage": "Without checking who's calling it, this service could be used by anyone on the internal network as a stepping stone into sensitive systems.",
      "requirement": {
        "title": "Authenticate and authorize callers",
        "given": "A request to resize an image from a URL is received",
        "when": "The caller's identity is not verified or not authorized for this operation",
        "then": "The request is rejected"
      }
    }
  ]
}
